Translate the following GNU C++ code to Java 8 code. The code reads and writes I/O from the console. Your translated code should have the exact same functionality as the given code, meaning that it should have the same output for any given input.
Print your translated code and also the confidence score you give to your translation. The confidence score should be a number between 0 and 1. The format of the output should be:
<translated_code>
<your_translated_code>
</translated_code>
<confidence>
<your_confidence_score>
</confidence>
Do not provide any other text or markdown fences.

Here is the original GNU C++ code you have to translate:
<original_code>
#include <bits/stdc++.h>
using namespace std;

const int INF = 10000000;
const int N = 210;
const int M = 21000;

struct Edge { int v, w; } edges[M];
int nxtEdge[M], firstEdge[N], edgeCnt;

void addEdge(int u, int v, int w) {
    edges[edgeCnt].v = v; edges[edgeCnt].w = w; nxtEdge[edgeCnt] = firstEdge[u]; firstEdge[u] = edgeCnt++;
    edges[edgeCnt].v = u; edges[edgeCnt].w = 0; nxtEdge[edgeCnt] = firstEdge[v]; firstEdge[v] = edgeCnt++;
}

int S, T;
int dist[N], q[N*2], curEdge[N], gap[N], inQueue[N], parent[N];

int dinicSAP(int s, int t) {
    memset(curEdge, -1, sizeof(curEdge));
    memset(parent, -1, sizeof(parent));

    int qf = 0, qr = 0;
    q[qr++] = t;
    inQueue[t] = 1;
    gap[0]++;
    dist[t] = 0;

    while (qf < qr) {
        int u = q[qf++];
        for (int i = firstEdge[u]; i != -1; i = nxtEdge[i]) {
            int v = edges[i].v;
            if (!inQueue[v]) {
                q[qr++] = v;
                inQueue[v] = 1;
                dist[v] = dist[u] + 1;
                gap[dist[v]]++;
                curEdge[v] = firstEdge[v];
            }
        }
    }

    int low = INF, u = s, ans = 0;
    parent[s] = s;

    while (dist[s] < t) {
        bool flag = false;
        for (int &i = curEdge[u]; i != -1; i = nxtEdge[i]) {
            if (edges[i].w && dist[edges[i].v] + 1 == dist[u]) {
                flag = true;
                low = min(low, edges[i].w);
                parent[edges[i].v] = u;
                u = edges[i].v;
                if (u == t) {
                    while (u != s) {
                        u = parent[u];
                        edges[curEdge[u]].w -= low;
                        edges[curEdge[u] ^ 1].w += low;
                    }
                    ans += low;
                    low = INF;
                }
                break;
            }
        }
        if (flag) continue;

        int mindis = t + 1;
        for (int i = firstEdge[u]; i != -1; i = nxtEdge[i]) {
            if (edges[i].w && mindis > dist[edges[i].v]) {
                mindis = dist[edges[i].v];
                curEdge[u] = i;
            }
        }
        gap[dist[u]]--;
        if (gap[dist[u]] == 0) return ans;
        dist[u] = mindis + 1;
        gap[dist[u]]++;
        u = parent[u];
    }
    return ans;
}

char grid1[12][12], grid2[12][12];
int sci[12][12], ca[12][12], rock[62][12][12];
int reach[62][12][12][12][12];
int vis[12][12];
int dir[4][2] = {{-1,0},{1,0},{0,-1},{0,1}};
int n, timeLimit;

void readInput() {
    scanf("%d%d", &n, &timeLimit);
    for (int i = 1; i <= n; ++i) {
        scanf("%s", grid1[i] + 1);
        for (int j = 1; j <= n; ++j) {
            if (grid1[i][j] == 'Z') rock[0][i][j] = 2;
            else if (grid1[i][j] == 'Y') rock[0][i][j] = 1;
            else sci[i][j] = grid1[i][j] - '0';
        }
    }
    for (int i = 1; i <= n; ++i) {
        scanf("%s", grid2[i] + 1);
        for (int j = 1; j <= n; ++j) {
            if (grid2[i][j] >= '0' && grid2[i][j] <= '9')
                ca[i][j] = grid2[i][j] - '0';
        }
    }
}

void expandStones() {
    for (int k = 1; k <= timeLimit; ++k) {
        for (int i = 1; i <= n; ++i) {
            for (int j = 1; j <= n; ++j) {
                if (rock[k-1][i][j] == 1) {
                    rock[k][i][j] = 1;
                } else if (rock[k-1][i][j] == 2) {
                    rock[k][i][j] = 2;
                } else {
                    for (int z = 0; z < 4; ++z) {
                        int nx = i + dir[z][0];
                        int ny = j + dir[z][1];
                        if (nx >= 1 && nx <= n && ny >= 1 && ny <= n) {
                            if (rock[k-1][nx][ny] == 2) {
                                rock[k][i][j] = 2;
                            }
                        }
                    }
                }
            }
        }
    }
}

void searchPath(int x, int y, int nowx, int nowy, int k) {
    vis[nowx][nowy] = 1;
    reach[k][x][y][nowx][nowy] = 1;
    if (k >= timeLimit || rock[k][nowx][nowy]) return;
    for (int z = 0; z < 4; ++z) {
        int nx = nowx + dir[z][0];
        int ny = nowy + dir[z][1];
        if (nx >= 1 && nx <= n && ny >= 1 && ny <= n && !vis[nx][ny]) {
            if (rock[k][nx][ny]) continue;
            searchPath(x, y, nx, ny, k + 1);
        }
    }
}

void computeReach() {
    for (int i = 1; i <= n; ++i)
        for (int j = 1; j <= n; ++j)
            if (sci[i][j]) {
                memset(vis, 0, sizeof(vis));
                searchPath(i, j, i, j, 0);
            }

    for (int k = 1; k <= timeLimit; ++k)
        for (int x = 1; x <= n; ++x)
            for (int y = 1; y <= n; ++y)
                for (int nx = 1; nx <= n; ++nx)
                    for (int ny = 1; ny <= n; ++ny)
                        reach[k][x][y][nx][ny] += reach[k-1][x][y][nx][ny];
}

void buildNetwork() {
    S = 0;
    T = n * n * 2 + 1;
    memset(firstEdge, -1, sizeof(firstEdge));
    edgeCnt = 0;

    for (int i = 1; i <= n; ++i)
        for (int j = 1; j <= n; ++j)
            addEdge(S, (i-1)*n + j, sci[i][j]);

    for (int i = 1; i <= n; ++i)
        for (int j = 1; j <= n; ++j)
            addEdge(n*n + (i-1)*n + j, T, ca[i][j]);

    for (int x = 1; x <= n; ++x)
        for (int y = 1; y <= n; ++y)
            for (int nx = 1; nx <= n; ++nx)
                for (int ny = 1; ny <= n; ++ny)
                    if (sci[x][y] && ca[nx][ny]) {
                        if (reach[timeLimit][x][y][nx][ny])
                            addEdge((x-1)*n + y, n*n + (nx-1)*n + ny, INF);
                    }
}

int main() {
    readInput();
    expandStones();
    computeReach();
    buildNetwork();

    int ans = dinicSAP(S, T);
    printf("%d\n", ans);
    return 0;
}
